import json


def run_deduplicated(calls, execute):
    seen = {}
    results = []
    for tool, args in calls:
        signature = json.dumps([tool, args], sort_keys=True)
        if signature not in seen:
            seen[signature] = execute(tool, args)
        results.append(seen[signature])
    return results
